import type { ClinicalOption } from "./clinical-types";
type AdvancedRenal = { harderFoils: ClinicalOption[]; harderStem?: string };
export const renalAdvancedB: Record<string, AdvancedRenal> = {};
function add(id:string,d:[string,string][],harderStem?:string){renalAdvancedB[id]={harderFoils:d.map(([text,why])=>({text,why})),...(harderStem?{harderStem}:{})};}

add("REN_overflow__mechanism",[["An involuntary contraction empties a normally filled bladder","That is a filling-phase overactivity mechanism, not leakage from substantial retention."],["Increased abdominal pressure exceeds urethral closure during coughing","That is the mechanism of stress leakage."],["An access barrier prevents use of the toilet despite normal emptying","The documented problem is retained bladder volume rather than access alone."]],"A patient has frequent dribbling, a persistently distended bladder, and a large residual after voiding. Which mechanism explains the leakage?");
add("REN_overflow__signs",[["Leakage immediately with coughing and no residual elevation","That supports stress leakage rather than incomplete emptying."],["Urgency followed by leakage with a low residual","That favors urgency-associated leakage."],["Dryness whenever help reaching the toilet is provided","That suggests a functional access problem."]],"A patient reports small frequent leaks. Which additional finding most strongly favors overflow from incomplete emptying over uncomplicated stress leakage?");
add("REN_overflow__complications",[["Repeated bloodstream seeding from an infected vascular catheter","Hematogenous infection is a different route; the vignette establishes retained bladder urine rather than a bloodstream source."],["Reflux caused by a congenital ureteral junction defect","Reflux can promote recurrent infections, but no congenital junction defect is established; the documented contributor is a large retained bladder volume."],["Loss of the local estrogen-dependent mucosal barrier","This can contribute in some patients but is not identified by the documented residual and recurrent infections."]],"A patient with a consistently large postvoid residual develops repeated symptomatic bacterial UTIs. Which factor most directly helps explain the recurrence?");
add("REN_overflow__tests",[["Peak urinary flow rate","Flow rate quantifies the stream, not the volume left in the bladder."],["Urine culture and susceptibility","Culture characterizes infection rather than directly measuring emptying."],["Serum creatinine concentration","Creatinine estimates renal filtration rather than retained bladder volume."]],"A patient has a weak stream and continued dribbling after attempted voiding. Which measurement most directly documents incomplete bladder emptying?");
add("REN_overflow__management",[["Use scheduled pad changes and a skin-protection regimen","These reduce consequences of leakage but do not correct significant retention."],["Start a detrusor-relaxing regimen for urgency-associated leakage","This addresses overactivity and can worsen emptying in a patient with retention."],["Begin pelvic-floor strengthening for cough-triggered leaks","This targets a stress mechanism rather than the documented retained urine."]],"A patient has frequent dribbling and a markedly elevated postvoid residual. Which plan addresses the underlying problem rather than only containing the leakage?");

add("REN_urge__risk",[["Failure of the detrusor to empty an overfilled bladder","That would favor retention and overflow, not this low-residual urgency pattern."],["Loss of urethral support during coughing","That produces stress-related leakage."],["Inability to reach an otherwise functioning toilet","That is a functional barrier rather than the bladder abnormality."]],"A patient with neurologic disease has sudden urgency, involuntary filling-phase contractions, and a low postvoid residual. Which bladder problem contributes to the accidents?");
add("REN_urge__mechanism",[["Passive leakage from a chronically overdistended bladder","That is an overflow mechanism."],["Inadequate urethral closure during a pressure-producing cough","That is a stress mechanism."],["A physical barrier delays getting to the toilet despite normal bladder behavior","That is functional incontinence, not the measured contraction abnormality."]],"During filling-phase urodynamics, urine loss occurs with an involuntary bladder contraction rather than a cough. Which mechanism best explains the leakage?");
add("REN_urge__signs",[["I leak when I cough but do not feel urgency beforehand","That is more characteristic of stress leakage."],["I dribble and still feel full after trying to empty","That raises concern for retention and overflow."],["I stay dry when someone helps me manage my clothing","That points toward a functional toileting barrier."]],"A nurse asks patients to describe the moments before urinary leakage. Which report most strongly supports urgency-associated incontinence?");
add("REN_urge__complications",[["Begin a daily pelvic-floor exercise program","This may support longer-term continence but does not directly correct the current unsafe rush to a distant bathroom."],["Use more absorbent continence products","Products contain urine but do not directly reduce the transfer and rushing hazard."],["Start a voiding diary before changing the toileting arrangement","A diary can guide treatment, but immediate safe access should not wait for a record of more near falls."]],"An older patient with urgency has almost fallen while rushing to a distant toilet. Which intervention best reduces this immediate safety risk?");
add("REN_urge__tests",[["A postvoid bladder scan","A residual measurement evaluates emptying, not the timing and triggers of recurrent accidents."],["Urinalysis and culture","These investigate infection but do not record the circumstances of episodes across the day."],["A frequency-volume estimate based on one observed void","One event does not characterize the repeated urgency and leakage pattern."]],"A patient has recurrent urgency-related accidents but cannot recall their timing or triggers. Which record would best guide the next clinical assessment?");
add("REN_urge__management",[["Intermittent catheterization for a persistently retained bladder volume","That addresses retention rather than the documented low-residual urgency problem."],["Pelvic support surgery for demonstrable stress leakage","This targets urethral support failure rather than the described urgency mechanism."],["Use an indwelling catheter to replace behavioral toileting treatment","Catheter drainage is not the first conservative bladder-training strategy for this presentation."]],"A patient with urgency-related leakage has no active infection and a low residual. Which prescribed conservative strategy should the nurse reinforce?");

add("REN_functional__risk",[["Demonstrated involuntary filling-phase detrusor contractions","That would establish a different bladder mechanism."],["A persistently large residual from outlet obstruction","That would support retention-associated leakage."],["Loss of urethral closure specifically during coughing","That is a stress mechanism rather than the access problem described."]],"A patient with dementia voids adequately when assisted but cannot identify the bathroom in an unfamiliar ward. Which factor best explains the accidents?");
add("REN_functional__mechanism",[["A large retained urine volume passively overflows","The case specifies a practical barrier rather than incomplete emptying."],["Involuntary bladder contraction during filling","No contraction abnormality is established by the clothing problem."],["Urethral support fails only when the patient coughs","The accidents occur because toileting is delayed, not specifically with coughing."]],"A patient recognizes the need to void and empties normally when assisted, but cannot undo complicated clothing in time. Why does leakage occur?");
add("REN_functional__signs",[["A large residual remains despite prompt toilet access","That suggests an emptying disorder rather than access alone."],["Leakage occurs with each cough despite ready assistance","That supports stress leakage."],["A bladder contraction causes loss before the patient can signal for help","That suggests urgency-related bladder overactivity."]],"A patient has accidents when the call bell is inaccessible. Which observation most strongly supports a functional access problem?");
add("REN_functional__complications",[["Control moisture with absorbent products while keeping the existing assistance schedule","Containment helps skin exposure but leaves the documented toileting delay uncorrected."],["Begin detrusor-relaxing treatment for presumed bladder overactivity","The case establishes an access problem, not an overactivity mechanism."],["Treat the irritation with a topical antifungal as the primary plan","The case describes moisture-associated irritation; treatment must address exposure and timely assistance rather than assume a fungal cause."]],"A mobility-limited patient has moisture-associated perineal irritation after repeated delayed toileting. Which goal addresses both the injury and its contributor?");
add("REN_functional__tests",[["A bladder scan immediately after voiding","This evaluates retained volume rather than the functional access and cognition barriers."],["Urodynamic assessment of filling-phase contractions","This assesses bladder behavior rather than the practical changes after ward admission."],["A cough stress test","A cough test evaluates stress leakage rather than the ability to locate and reach the toilet."]],"A previously continent patient develops accidents after admission to a new ward. Which assessment most directly explores a functional explanation?");
add("REN_functional__management",[["Start pelvic-floor exercises for stress leakage","This does not directly remove the transfer barrier in a patient who empties adequately."],["Use a bladder-relaxing medicine to suppress urgency","The documented cause is delayed assistance, not detrusor overactivity."],["Provide additional absorbent pads at the bedside","Pads contain leakage but do not directly restore timely toilet access."]],"A patient empties adequately but cannot transfer quickly enough without help. Which nursing change directly addresses the accidents?");

add("REN_retention__risk",[["The new medication is treating stress-related urethral closure weakness","Anticholinergic effects reduce detrusor activity rather than strengthening urethral support."],["The new symptoms indicate improved bladder storage without an emptying effect","Increasing incomplete emptying raises concern for a drug-related retention effect."],["The medication has reduced outlet resistance enough to restore emptying","The worsening residual suggests impaired emptying, not successful reduction of resistance."]],"A patient with prostate-related outlet symptoms develops more incomplete emptying after an anticholinergic is added. Which concern should the nurse communicate?");
add("REN_retention__mechanism",[["An abrupt strong contraction empties a normally filled bladder","That is not the impaired contraction specified."],["Urine leaks solely because abdominal pressure rises with a cough","That does not explain the large postvoid residual."],["The bladder empties normally but toilet access is delayed","The measured residual establishes an emptying problem."]],"Urodynamic evaluation identifies weak detrusor contraction, and a large urine volume remains after voiding. Which process explains the residual?");
add("REN_retention__signs",[["Leakage during a cough with an otherwise strong stream","That pattern favors stress leakage rather than a bladder remaining distended after voiding."],["Sudden urgency followed by a complete void","A complete void does not demonstrate retained volume."],["Burning at the urethral opening during urination","Dysuria suggests irritation or inflammation but does not itself establish retention."]],"A patient dribbles repeatedly but still feels full after attempted voiding. Which finding most strengthens concern for retained bladder urine?");
add("REN_retention__complications",[["A focal renal cortical scar from a prior vascular infarct","A vascular infarct is a different mechanism from pressure transmitted upstream by retained urine."],["Multiple inherited cysts replacing renal parenchyma","Inherited cyst formation is not the structural result of chronic bladder back pressure."],["Glomerular inflammation from circulating immune complexes","An immune glomerular lesion is distinct from pressure-related collecting-system dilation."]],"A patient with longstanding retention develops recurrent infections. Which additional structural complication can result from sustained back pressure?");
add("REN_retention__tests",[["Urine culture","Culture can detect infection but does not directly measure residual bladder volume."],["Serum creatinine measurement","Creatinine assesses renal function rather than the volume remaining immediately after a void."],["Uroflowmetry","Flow-rate testing characterizes the stream rather than directly measuring the postvoid residual."]],"A patient reports persistent fullness immediately after voiding. Which noninvasive bedside test directly assesses whether urine remains in the bladder?");
add("REN_retention__management",[["Begin a detrusor-relaxing medicine for urgency","Further detrusor relaxation does not relieve acute painful retention and may worsen emptying."],["Use scheduled voiding attempts as the initial treatment","A markedly distended painful bladder needs prompt emptying rather than a behavioral schedule alone."],["Begin long-term prostate-shrinking therapy as the immediate intervention","Such treatment may address selected causes over time but does not promptly decompress the acutely retained bladder."]],"A patient has acute painful inability to void with a markedly distended bladder. Which ordered treatment should the nurse anticipate?");

add("REN_stricture__risk",[["Prostate enlargement causing external outlet compression","That is a different possible obstruction source from post-traumatic urethral scarring."],["An involuntary contraction of a normally unobstructed bladder","Overactivity is not a scar-related late complication."],["Stress leakage from reduced pelvic support alone","That is a different mechanism from urethral scar formation."]],"Months after urethral trauma and instrumentation, a patient develops progressive outflow symptoms. Which late complication warrants evaluation?");
add("REN_stricture__mechanism",[["Weak detrusor contraction reduces the force available to empty","Weak contraction is another cause of a poor stream, but the specified lesion is a narrowed outlet."],["Involuntary detrusor contraction occurs during filling","This explains urgency rather than the resistance created by a fibrotic urethral segment."],["Reduced pelvic support allows leakage when abdominal pressure rises","This describes stress leakage rather than increased resistance to outflow."]],"A fibrotic segment narrows a patient's urethral lumen. Which mechanism explains the increased effort needed to pass urine?");
add("REN_stricture__signs",[["Cough-triggered leakage with a strong unobstructed stream","That is more consistent with stress leakage."],["Urgency followed by a complete, forceful void","That is less characteristic of worsening fixed narrowing."],["Improved emptying and a falling residual after treatment","Those are reassuring rather than obstructive trends."]],"A patient with known urethral narrowing reports changes in voiding. Which pattern most suggests progressive outflow obstruction?");
add("REN_stricture__complications",[["Primary immune-complex glomerulonephritis","The structural outflow obstruction and retained urine instead support pressure-related renal injury."],["Prerenal hypoperfusion from gastrointestinal fluid loss","No volume-loss trigger is established; severe obstruction provides the direct explanation."],["An intrinsic tubular toxic injury after a new nephrotoxin","The case identifies a severe outflow lesion rather than a new toxic exposure."]],"A patient with severe urethral narrowing has a large residual and worsening kidney function. Which complication should be considered?");
add("REN_stricture__tests",[["Urine culture and susceptibility","Culture identifies infection rather than defining the urethral anatomy."],["Uroflowmetry","Flow measurement may support obstruction but does not directly locate and define the scarred segment."],["Postvoid residual measurement","Residual volume documents incomplete emptying without mapping the structural narrowing."]],"A patient has a persistent weak spraying stream after prior urethral instrumentation. Which investigation can directly define the suspected structural narrowing?");
add("REN_stricture__management",[["Use pelvic-floor strengthening as the primary treatment","Strengthening does not remove a fixed urethral scar causing outflow resistance."],["Treat as detrusor overactivity with a bladder-relaxing regimen","Relaxing the bladder does not correct the confirmed anatomic narrowing."],["Use an alpha blocker as definitive treatment of the scar","Reducing smooth-muscle tone does not remove a fibrotic urethral lesion; a structural urologic plan is needed."]],"A symptomatic urethral stricture is confirmed as the cause of poor outflow. Which plan addresses the structural lesion?");

add("REN_UTI__risk",[["The catheter protects against infection by continuously emptying the bladder","Drainage does not eliminate the catheter-associated route for bacterial entry."],["Visible leakage ensures enough washout to offset a large residual","Leakage does not establish complete emptying or eliminate retained-urine risk."],["Diabetes makes a positive culture diagnostic of current symptomatic infection","Diabetes can increase risk, but symptoms and clinical assessment distinguish infection from asymptomatic bacteriuria."]],"A patient with diabetes has a large residual and an indwelling urinary catheter. Which explanation supports the need for careful infection-prevention measures?");
add("REN_UTI__mechanism",[["Hematogenous spread from a distant infected site","Bloodstream spread can occur, but ascent from periurethral enteric organisms is the common route described."],["An immune response injures the glomerular filtration membrane","Immune glomerular disease is not the route by which nearby enteric organisms infect the bladder."],["Extension outward from an infected renal cyst","This is a different source from organisms at the urethral opening."]],"A patient asks how enteric organisms near the urethral opening can produce a bladder infection. Which route most commonly explains this process?");
add("REN_UTI__signs",[["Investigating medication changes and other causes of delirium","That is an appropriate assessment step, not the diagnostic error to avoid."],["Reviewing hydration and other clinical findings before attributing confusion to infection","A broader evaluation is appropriate in this stable presentation."],["Observing closely and reassessing if local urinary or systemic signs develop","Careful observation and reassessment are appropriate, not the specified error."]],"An older patient has acute confusion but is afebrile, hemodynamically stable, and has no local urinary symptoms. Even if bacteriuria is found, which diagnostic error should the nurse avoid?");
add("REN_UTI__complications",[["Persistent uncomplicated cystitis","Rigors, fever, and costovertebral discomfort suggest progression beyond an isolated lower bladder infection."],["Urethritis","Urethral inflammation does not best explain the new upper-tract pain and systemic illness."],["Asymptomatic bacteriuria","The patient now has systemic and upper-tract symptoms rather than bacteriuria without illness."]],"A patient treated for symptomatic cystitis develops rigors, fever, and costovertebral discomfort. Which progression is most concerning?");
add("REN_UTI__tests",[["A first-catch specimen collected as for urethral STI testing","The ordered routine bacterial culture calls for the instructed clean-catch midstream approach, not a different sampling objective."],["Urine transferred from a collection pan after voiding","Transfer from a nonsterile collection surface can introduce contaminating organisms."],["A voided specimen collected in a clean household container","A routine culture requires an appropriate sterile collection container and the instructed collection method."]],"A patient can void independently and needs a routine bacterial urine culture. Which collection method best limits contamination for the ordered sample?");
add("REN_UTI__management",[["Continue the empiric drug even when the isolate is resistant to it","The susceptibility result should inform review of the antimicrobial plan."],["Treat until the first symptom-free day rather than follow the prescribed course","Symptom relief alone does not determine the appropriate regimen duration."],["Change to a broader-spectrum drug rather than use the susceptibility result","Selection should fit the identified organism and clinical context rather than breadth alone."]],"A symptomatic patient's culture identifies a bacterial pathogen and its susceptibilities. Which principle should guide the prescribed antimicrobial treatment?");

add("REN_urethritis__risk",[["The exposure history establishes bacterial infection of the kidney","Sexual exposure and urethral discharge point to possible urethral pathogens rather than proving upper-tract infection."],["Discharge after exposure is explained by prostate enlargement","Benign enlargement does not account for possible STI-associated mucosal inflammation."],["A lack of flank pain makes an infectious cause unlikely","Urethral infection does not require upper-tract pain."]],"A patient with urethral discharge is asked about sexual exposures and partner symptoms. Why is this history relevant to the assessment?");
add("REN_urethritis__mechanism",[["The renal pelvis and parenchyma","Those are upper-tract structures rather than the primary site of urethritis."],["The glomerular filtration membrane","Glomerular inflammation is a different renal process."],["The bladder detrusor as an isolated contractile disorder","A contraction abnormality does not define urethral mucosal inflammation."]],"A patient has dysuria and a discharge originating from the urethral opening, without an upper-tract pattern. Which tissue is primarily inflamed in urethritis?");
add("REN_urethritis__signs",[["A large residual after voiding without discharge","That more directly supports incomplete emptying."],["Leakage specifically during coughing with normal emptying","That favors stress incontinence."],["Heavy proteinuria with periorbital edema","That points toward a glomerular protein-loss process."]],"A patient reports burning during urination. Which additional finding particularly supports a urethral inflammatory process needing targeted sexual-health evaluation?");
add("REN_urethritis__complications",[["Resolution of dysuria establishes microbiologic cure in both partners","Symptom improvement in one person does not establish partner treatment or cure."],["New symptoms after treatment indicate drug intolerance rather than reexposure","Reinfection or persistent infection remains possible and needs assessment."],["Partners need assessment only if urethral discharge becomes visible","Asymptomatic infection can still require recommended partner management."]],"A patient treated for sexually transmitted urethritis reports rapid symptom relief. Why are completion, exposure precautions, and follow-up teaching still important?");
add("REN_urethritis__tests",[["Routine midstream urine bacterial culture","Routine culture does not replace recommended targeted testing for common gonococcal and chlamydial infection."],["Urine leukocyte esterase testing","Leukocyte esterase can support inflammation but does not identify these specific organisms."],["Serologic syphilis testing","Syphilis screening may be relevant to sexual-health care but does not identify the common urethral gonococcal or chlamydial pathogen."]],"A patient has urethral discharge after a possible sexual exposure. Which ordered test can identify common gonococcal or chlamydial infection?");
add("REN_urethritis__management",[["Resume sexual activity when burning first improves","Symptom improvement is not the endpoint for the recommended treatment and exposure precautions."],["Arrange partner treatment only when the partner has symptoms","Partners can have asymptomatic infection and still need recommended evaluation or treatment."],["Use a shared leftover antibiotic course for the partner","Partner care should follow an appropriate recommended plan rather than an unassessed leftover regimen."]],"A patient receives organism-directed treatment for STI-associated urethritis. Which additional component helps reduce reinfection and onward transmission?");

add("REN_chronic_pyelo__risk",[["The blockage protects renal tissue by reducing urine flow through it","Impaired drainage promotes stasis rather than protecting against recurrent infection."],["The blockage affects lower-tract symptoms but not upper-tract recurrence","An unresolved drainage problem can contribute to recurrent kidney infection."],["Once symptoms improve, persistent obstruction no longer contributes to risk","Symptom relief does not eliminate the structural contributor to future episodes."]],"A patient has repeated culture-confirmed kidney infections and an unresolved drainage blockage. Why is correcting the blockage an important part of prevention?");
add("REN_chronic_pyelo__mechanism",[["Inherited cyst expansion compresses otherwise uninfected renal tissue","That is a different structural disease from scarring after repeated documented infections."],["Persistent vascular narrowing reduces nephron perfusion","Vascular injury is another chronic renal mechanism, but the case ties the scars to repeated febrile upper-tract infections."],["Immune-complex deposition causes a glomerular inflammatory lesion","Immune nephritis is distinct from repeated upper-tract infection with subsequent parenchymal scarring."]],"After repeated febrile upper urinary infections, imaging shows deformed scarred renal tissue. Which process most directly accounts for this structural change?");
add("REN_chronic_pyelo__signs",[["Stable eGFR with consistently controlled blood pressure","Stable renal function is less supportive of progressive chronic renal consequences."],["Isolated dysuria with preserved filtration","Lower-tract irritation does not establish worsening chronic renal function."],["Brief urinary frequency that resolves after the acute episode","A transient symptom pattern is less concerning for chronic scarring-related decline than a sustained renal-function trend."]],"A patient with recurrent upper-tract infections and known scarring develops hypertension. Which additional trend should prompt follow-up for chronic renal consequences?");
add("REN_chronic_pyelo__complications",[["Progressive inherited renal cyst formation","Cyst formation is a different structural disease from inflammatory scarring after repeated infection."],["Immune-complex nephritis after streptococcal illness","This is a distinct postinfectious glomerular process rather than scarring from recurrent pyelonephritis."],["Pelvic support failure causing stress leakage","Stress continence mechanisms do not describe the long-term injury to renal parenchyma."]],"A patient with repeated documented pyelonephritis asks about the long-term kidney risk. Which consequence should the nurse explain?");
add("REN_chronic_pyelo__tests",[["Bladder diary and pelvic-floor examination","These assess voiding patterns and support rather than the pathogen and renal anatomy."],["Serum creatinine and electrolytes","These assess renal consequences but do not identify the organism or directly define a structural contributor."],["Urinalysis and inflammatory markers","These can support inflammation but do not provide the organism-directed and anatomic information requested."]],"A patient has recurrent febrile upper urinary infections. Which evaluation can assess the responsible organism and investigate a structural contributor?");
add("REN_chronic_pyelo__management",[["Treat each episode empirically while postponing structural drainage evaluation","Symptomatic treatment leaves the documented recurrence contributor unaddressed."],["Correct drainage and wait to treat the current culture-positive infection","Both the active infection and the structural cause need appropriate care."],["Use suppressive antimicrobial treatment as a substitute for assessing the obstruction","A preventive medication strategy does not remove the need to address a correctable drainage lesion."]],"A patient has another culture-confirmed upper urinary infection in the setting of an anatomic obstruction. Which plan most directly addresses both the episode and recurrence risk?");

add("REN_poststrep__risk",[["The urine discoloration reflects bacterial invasion of the bladder","The delayed edema and dark urine after streptococcal infection support a glomerular process rather than simple cystitis."],["The preceding infection directly obstructed the ureter with a stone","No stone mechanism links the documented delayed immune nephritis to the earlier skin infection."],["Persistent bacteria must still be growing inside the renal parenchyma","Poststreptococcal nephritis is immune mediated and does not require ongoing bacterial renal invasion."]],"A child develops edema and cola-colored urine several weeks after a documented streptococcal skin infection. Why is the preceding infection clinically relevant?");
add("REN_poststrep__mechanism",[["A ureteral stone physically blocking urine drainage","Obstruction does not explain the postinfectious glomerular inflammatory pattern."],["Direct muscle breakdown releasing myoglobin","That is a different cause of dark urine and kidney injury."],["Bacterial ascent limited to the bladder mucosa","That does not describe immune glomerular injury."]],"A child develops red-cell casts, edema, and impaired filtration after streptococcal illness. Which mechanism best explains the renal findings?");
add("REN_poststrep__signs",[["Orthostatic hypotension with evidence of volume depletion","Salt and water retention in this presentation instead warrants close hypertension monitoring."],["Urethral discharge","Discharge suggests a lower urethral inflammatory process rather than renal salt and water retention."],["Painful bladder distention with a large residual","That suggests a lower outflow problem rather than the nephritic fluid-balance pattern."]],"A child with postinfectious nephritis has cola-colored urine and facial edema. Which additional finding should be monitored because of the renal salt and water disturbance?");
add("REN_poststrep__complications",[["An isolated lower urinary infection","Cystitis does not explain rapid weight gain and bilateral pulmonary crackles."],["Intravascular volume depletion","The edema, weight gain, and pulmonary findings instead suggest volume excess."],["A focal pulmonary infection without volume overload","A lung infection is a competing respiratory problem, but rapid weight gain during nephritis makes fluid overload the priority."]],"A child with acute nephritis develops increasing work of breathing, bilateral crackles, and rapid weight gain. Which complication should be assessed first?");
add("REN_poststrep__tests",[["A positive urine culture with dysuria","This supports a urinary infection rather than demonstrating a postinfectious glomerular lesion."],["Urine heme with absent red cells and a markedly elevated creatine kinase","That pattern suggests muscle pigment release rather than red-cell casts from nephritis."],["A large residual with bilateral collecting-system dilation","That pattern points toward obstruction rather than an immune glomerular process."]],"A child has dark urine and edema after a recent throat infection. Which investigative pattern most supports a postinfectious glomerular process?");
add("REN_poststrep__management",[["Encourage fluid loading to flush the discolored urine","Fluid loading can worsen the salt and water excess causing edema and hypertension."],["Focus on urinary discomfort and routine discharge teaching","The acute risks require active blood-pressure and fluid-balance monitoring."],["Use antimicrobial response as the principal measure of renal recovery","Treating the preceding infection does not replace monitoring the immune renal complication and volume effects."]],"A child with poststreptococcal nephritis has edema and elevated blood pressure. Which nursing focus addresses the principal acute renal risks?");

add("REN_dialysis__risk",[["Use entry into a particular eGFR category as the starting criterion","A category does not by itself incorporate symptoms, complications, or trajectory."],["Use the daily urine volume as the principal starting criterion","Urine production does not establish adequate solute or fluid clearance."],["Use the creatinine concentration as the starting criterion","Creatinine alone does not characterize dangerous electrolyte, acid-base, volume, or uremic complications."]],"A patient with advanced kidney dysfunction asks why dialysis timing cannot be decided from a single eGFR number. Which explanation is most appropriate?");
add("REN_dialysis__mechanism",[["Blood exchanges solutes across synthetic hollow fibers in an external dialyzer","That describes hemodialysis rather than exchange across the abdominal peritoneum."],["Blood undergoes convective solute removal through an extracorporeal hemofilter","This describes an extracorporeal filtration modality rather than peritoneal exchange."],["A donor kidney filters plasma across its glomerular capillaries","That describes filtration after transplantation, not the membrane used in peritoneal dialysis."]],"A patient selects home peritoneal dialysis. Which description explains the membrane across which solute exchange occurs in this treatment?");
add("REN_dialysis__signs",[["Reduced red-cell mass","Anemia can contribute to dyspnea but does not account for new edema and crackles after missed fluid removal."],["Excess fluid removal with intravascular depletion","The findings indicate retained fluid after missed dialysis rather than volume depletion from excessive removal."],["An isolated increase in retained nitrogenous solutes","Uremic solutes can cause illness, but the edema and pulmonary findings most directly indicate volume accumulation."]],"After missing dialysis, a patient has increasing peripheral edema, crackles, and worsening dyspnea. Which accumulated burden best explains the pattern?");
add("REN_dialysis__complications",[["Mechanical catheter outflow obstruction","An outflow problem can impair exchanges but does not best explain cloudy effluent with abdominal pain."],["Exit-site infection","An exit-site process centers on local external signs rather than the described intraperitoneal inflammatory pattern."],["Dialysate leakage into the abdominal wall","Leakage may cause local swelling and exchange problems, whereas cloudy painful exchanges raise concern for peritonitis."]],"A patient performing peritoneal dialysis develops abdominal pain and newly cloudy effluent. Which complication requires prompt evaluation?");
add("REN_dialysis__tests",[["Arteriovenous access thrill and bruit","These assess access function rather than the net clinical volume response."],["Pre- and postdialysis urea concentrations","Urea measurements address solute removal rather than the complete immediate volume assessment."],["Hemoglobin and iron studies","These inform anemia care rather than the response to planned fluid removal."]],"A patient has just completed hemodialysis with planned fluid removal. Which assessment set best evaluates the immediate clinical volume response?");
add("REN_dialysis__management",[["Recheck patency after starting the planned treatment through the fistula","A newly absent thrill requires evaluation before use rather than a trial of dialysis through a possibly compromised access."],["Proceed because a distal arterial pulse is present","A distal pulse does not establish fistula patency."],["Monitor the site until the next scheduled session if the skin is intact","Normal skin does not exclude an access flow problem requiring prompt assessment."]],"Before hemodialysis, a patient's mature arteriovenous fistula has lost its previously palpable thrill. Which action best addresses the possible change in patency?");

add("REN_acidosis__risk",[["Excess renal bicarbonate regeneration","Regenerating more bicarbonate would oppose metabolic acidosis rather than explain the renal capacity loss."],["Loss of gastric hydrogen ions","Gastric acid loss tends toward metabolic alkalosis rather than the renal acid-retention mechanism."],["Primary alveolar hypoventilation","Hypoventilation produces a primary respiratory acid disturbance, not the lost renal acid-excretion capacity asked about."]],"As kidney function progressively declines, a patient develops persistent metabolic acidosis. Which loss of renal capacity directly contributes?");
add("REN_acidosis__mechanism",[["Hypoventilation raises carbon dioxide as the initiating defect","That describes primary respiratory acidosis rather than retained nonvolatile acid in kidney failure."],["Gastric hydrogen loss raises circulating bicarbonate","That favors metabolic alkalosis rather than the low-bicarbonate pattern."],["Excess renal acid removal depletes circulating bicarbonate","Removing acid would reduce the acid burden rather than explain this renal retention pattern."]],"A patient with advanced renal dysfunction has low bicarbonate and retained acid. Which explanation best connects these changes to kidney function?");
add("REN_acidosis__signs",[["A primary respiratory alkalosis initiating the low bicarbonate","The case identifies severe metabolic acidosis; increased ventilation is the compensatory response rather than the initiating disorder."],["Reduced alveolar ventilation causing carbon dioxide retention","Deep rapid breathing tends to lower carbon dioxide, not retain it."],["A renal response that increases bicarbonate excretion","The visible respiratory pattern is a pulmonary compensatory response rather than renal bicarbonate loss."]],"A patient with severe metabolic acidosis develops deep rapid respirations while being assessed. What physiologic response does this pattern most directly represent?");
add("REN_acidosis__complications",[["Erythropoietin deficiency reducing red-cell production","This is another CKD consequence but is not the acidosis-related mechanism of muscle catabolism and adverse bone effects."],["Uremic platelet dysfunction causing bruising","Platelet dysfunction is a different CKD complication, not the direct consequence asked about."],["Renal sodium retention causing extracellular fluid expansion","Volume excess is important but is distinct from the chronic acid-related tissue effects."]],"A patient with CKD has sustained metabolic acidosis and progressive muscle wasting. Which chronic consequence is relevant to the acid-base disturbance itself?");
add("REN_acidosis__tests",[["Elevated bicarbonate with alkalemia","That supports a metabolic alkalotic pattern."],["Acidemia with a primary carbon dioxide increase and preserved bicarbonate","That is more consistent with a primary respiratory acid disturbance."],["Alkalemia with low carbon dioxide and a secondary bicarbonate decrease","This supports primary respiratory alkalosis rather than renal metabolic acidosis."]],"A patient with advanced renal disease is assessed for a metabolic acid-base disturbance. Which blood-test pattern supports renal metabolic acidosis?");
add("REN_acidosis__management",[["Hemoglobin, reticulocyte count, and iron indices","These monitor anemia rather than alkali response and associated electrolyte or volume effects."],["Parathyroid hormone, phosphate, and bone density","These assess CKD mineral-bone disease rather than the immediate acid-base treatment response."],["Urinary urgency frequency and postvoid residual","These assess lower-tract function rather than systemic acid-base correction."]],"A patient with CKD begins a prescribed alkali regimen for persistent metabolic acidosis. Which follow-up set best evaluates response and treatment effects?");

add("REN_anemia__risk",[["Reduced renin release","Renin participates in pressure and volume regulation rather than directly stimulating marrow red-cell production."],["Reduced calcitriol production","Calcitriol participates in mineral regulation rather than serving as the principal erythropoietic signal."],["Reduced antidiuretic hormone activity","ADH regulates water handling rather than directly signaling erythropoiesis."]],"A patient with progressive CKD has declining hemoglobin without identified active blood loss. Which lost endocrine signal contributes to reduced red-cell production?");
add("REN_anemia__mechanism",[["Increase intestinal iron absorption through direct transport of iron","Erythropoietin primarily signals erythroid marrow production rather than directly transporting intestinal iron."],["Increase red-cell survival by preventing splenic removal","Its primary role is stimulation of production rather than direct prolongation of circulating cell lifespan."],["Increase the oxygen saturation of each existing hemoglobin molecule","It increases marrow red-cell production rather than directly changing hemoglobin saturation."]],"A patient asks why erythropoietin deficiency in kidney disease can lower hemoglobin. What does this hormone normally signal the body to do?");
add("REN_anemia__signs",[["Peripheral edema with crackles and rapid weight gain","That pattern favors fluid overload rather than specifically reduced red-cell mass."],["Paresthesias with carpopedal spasm","That points toward a calcium-related neuromuscular problem rather than typical anemia signs."],["Easy bruising with mucosal bleeding","This can suggest platelet dysfunction but is not the same manifestation as reduced oxygen-carrying red-cell burden."]],"A patient with low hemoglobin in CKD reports fatigue with previously tolerated activity. Which additional finding fits the reduced red-cell burden?");
add("REN_anemia__complications",[["Reduced alveolar oxygen transfer lowering hemoglobin saturation","The normal saturation does not support this as the explanation; anemia reduces total oxygen content even when saturation is normal."],["Reduced hemoglobin affinity as the defining consequence","The primary problem in anemia is less circulating hemoglobin, not an established affinity defect."],["Increased total oxygen content because each remaining cell is saturated","Normal saturation does not compensate for reduced total hemoglobin concentration."]],"A patient with substantial CKD-associated anemia develops exertional dyspnea despite a normal oxygen saturation reading. Which consequence of anemia helps explain the symptom?");
add("REN_anemia__tests",[["Serum bicarbonate and a blood-gas assessment","These address acid-base status rather than common reversible anemia contributors."],["Parathyroid hormone and vitamin D levels","These assess mineral-bone disease rather than providing the principal iron and alternate-anemia evaluation."],["Dialysis access flow assessment","Access evaluation does not establish iron availability or other causes of low hemoglobin."]],"Before selecting therapy for a patient with CKD and low hemoglobin, which further assessment helps identify reversible contributors and appropriate treatment needs?");
add("REN_anemia__management",[["Start erythropoiesis-directed treatment without correcting the documented iron deficit","Erythropoiesis requires available iron; the individualized plan must address the identified deficiency."],["Use transfusion as the routine initial long-term approach for stable CKD anemia","Treatment is individualized and should address reversible contributors rather than default to chronic transfusion."],["Treat fatigue with activity restriction while deferring the anemia plan","Activity changes do not correct the documented hemoglobin and iron problem."]],"A patient's CKD-associated anemia includes documented iron deficiency. Which treatment principle should guide the nursing explanation of the plan?");

add("REN_BPH__risk",[["Benign enlargement indicates malignant prostate transformation","BPH is benign growth and does not itself establish cancer."],["Urgency means the prostate cannot contribute to the symptoms","Storage symptoms can coexist with prostate-related outlet resistance."],["The symptom pattern establishes prostate size without further assessment","Symptoms alone do not define the anatomic size or exclude competing causes."]],"An older man asks how age relates to a diagnosis of benign prostate enlargement and new urinary symptoms. Which explanation is accurate?");
add("REN_BPH__mechanism",[["Weak urethral closure during abdominal pressure increases","This is the mechanism of stress leakage rather than poor flow from outlet resistance."],["Excess renal production of dilute urine","High urine production does not explain the obstructed weak stream and elevated residual."],["A detrusor contraction occurring prematurely during filling","Overactivity explains urgency leakage rather than the local prostate-related outflow resistance."]],"A patient with prostate enlargement has a weak stream and a rising postvoid residual. Which local mechanism most directly explains the incomplete emptying?");
add("REN_BPH__signs",[["Longstanding nocturia without any acute change","This is not as urgent as painful inability to void."],["Mild stable hesitancy with continued adequate emptying","The acute painful distention pattern is more concerning."],["A single cough-related leak without bladder fullness","That is less suggestive of acute retention."]],"A patient with chronic prostate-related outlet symptoms reports new changes. Which finding most strongly suggests acute retention requiring prompt assessment?");
add("REN_BPH__complications",[["Immune glomerular injury from a postinfectious response","That is a different renal mechanism from sustained urinary back pressure."],["Inherited renal cyst formation","Inherited cystic disease is not a consequence of prostate outlet obstruction."],["Renal hypoperfusion from acute systemic blood loss","Blood-loss hypoperfusion is a prerenal mechanism, not the stated chronic outflow obstruction."]],"A patient with severe prostate-related outflow obstruction has a large chronic residual. Which upper-tract complication can result if pressure remains unresolved?");
add("REN_BPH__tests",[["Maximum urinary flow rate","Flow rate describes the stream rather than directly measuring retained volume."],["Serum creatinine concentration","Creatinine assesses filtration rather than quantifying bladder urine left after voiding."],["A prostate symptom score","A score describes symptom burden but cannot directly measure the residual volume."]],"A patient with prostate-related symptoms reports that the bladder remains full after voiding. Which measurement directly evaluates the retained volume?");
add("REN_BPH__management",[["It reduces prostate tissue volume by blocking androgen conversion","That describes a different medication class rather than alpha blockade."],["It strengthens detrusor contractions by increasing cholinergic stimulation","Alpha blockade improves outflow by reducing smooth-muscle tone, not directly stimulating detrusor contraction."],["It suppresses filling-phase contractions through antimuscarinic activity","This is a different drug mechanism and does not explain the alpha blocker action."]],"A patient starting an alpha blocker for BPH asks how it may improve the stream. Which mechanism should the nurse explain?");

add("REN_PKD__risk",[["A history of a single simple renal cyst in an unrelated person","An unrelated simple cyst does not carry the inherited significance of an affected parent."],["A previous uncomplicated bladder infection","One lower UTI does not establish inherited cyst-forming disease risk."],["Age-associated prostate enlargement","BPH is a different process and is not the inherited mechanism of ADPKD."]],"An adult whose parent has autosomal dominant polycystic kidney disease asks which history most strongly influences personal risk assessment. Which factor matters most?");
add("REN_PKD__mechanism",[["A fixed urethral scar raises pressure behind the bladder outlet","That is an obstructive mechanism, not cyst-driven distortion of renal parenchyma."],["Immune complexes inflame the glomerular filter","An immune glomerular lesion is a different mechanism from expanding inherited cysts."],["Small renal arteries narrow from longstanding hypertension as the primary lesion","Vascular injury can coexist but does not describe the specified cyst-burden mechanism."]],"A patient with inherited renal cystic disease asks why filtration may decline as cyst burden increases. Which structural effect helps explain the loss of function?");
add("REN_PKD__signs",[["Attribute the blood to a routine lower UTI and begin an empiric plan","A new episode requires assessment of bleeding, infection, and other possible causes rather than assuming cystitis."],["Treat as a recurrent urinary stone without further evaluation","Stones are a possible cause but cannot be presumed from the known PKD alone."],["Observe until the next routine visit because hematuria can occur in PKD","A known possibility does not remove the need to assess a new symptomatic change."]],"A patient with established PKD develops new flank discomfort and visible blood in the urine. Which response best addresses the change?");
add("REN_PKD__complications",[["An isolated stress continence disorder","Stress leakage does not explain a sustained multiyear fall in renal filtration."],["A single short-lived prerenal episode","A sustained trend over years is not adequately explained by one transient volume-related event."],["A lower urinary infection without renal involvement","A lower-tract episode does not explain persistent progressive filtration loss."]],"A patient with PKD has a sustained decline in eGFR over several years. Which renal complication is this trend consistent with?");
add("REN_PKD__tests",[["Postvoid bladder ultrasound","This measures bladder emptying rather than characterizing the inherited renal cyst pattern."],["Urine culture and susceptibility","Culture identifies infection rather than renal cystic anatomy."],["Serial eGFR measurements","These assess function but do not directly show the renal structure needed for this question."]],"A patient has hypertension and a parent with PKD. Which evaluation can identify the expected renal anatomy in the relevant inherited context?");
add("REN_PKD__management",[["Plan aspiration of the largest cyst as the principal renal-protection strategy","Selected cyst interventions can address particular complications, but they do not replace blood-pressure control and longitudinal renal care."],["Manage flank pain while deferring blood-pressure treatment","Pain relief does not address hypertension-related risk to remaining renal function."],["Schedule follow-up when flank pain or urinary symptoms recur","Progressive renal consequences can develop without a reliable symptom warning, so symptom-triggered follow-up is insufficient."]],"A patient with PKD and elevated blood pressure asks how to protect remaining renal function. Which plan is most appropriate?");

add("REN_nephrosclerosis__risk",[["A family history of inherited bilateral renal cysts","That suggests a different pathway to chronic renal disease."],["Recurrent febrile kidney infections with vesicoureteral reflux","That supports an infectious and reflux-associated scarring process."],["A prolonged untreated urethral obstruction","That is a postrenal rather than pressure-mediated small-vessel mechanism."]],"A patient with gradual renal decline is evaluated for hypertensive nephrosclerosis. Which longitudinal history most strongly supports the pressure-related mechanism?");
add("REN_nephrosclerosis__mechanism",[["Increased glomerular filtration from improved downstream flow","Luminal narrowing reduces rather than improves downstream perfusion."],["A fixed outflow blockage raises pressure through the collecting system","That describes postrenal obstruction rather than small-vessel narrowing."],["Immune complexes directly disrupt the filtration membrane","This is a different initiating lesion from hypertension-related vascular injury."]],"Renal small vessels have thickened and narrowed after prolonged hypertension. Which consequence most directly links this vascular change to nephron injury?");
add("REN_nephrosclerosis__signs",[["An acute outflow obstruction established by the proteinuria","Proteinuria does not establish obstruction; the sustained decline with hypertension suggests chronic injury."],["A transient prerenal episode established by one low intake day","A sustained filtration trend cannot be attributed to a single brief intake change without supporting evidence."],["An uncomplicated bladder storage disorder","A storage disorder does not explain progressive loss of filtration with proteinuria."]],"A patient with longstanding hypertension has modest proteinuria and a sustained fall in eGFR. Which interpretation should guide follow-up?");
add("REN_nephrosclerosis__complications",[["An inherited increase in renal cyst burden","A cystic genetic process is different from progressive pressure-related vascular injury."],["A fixed urethral scar causing recurrent retention","A urethral lesion is an outflow disorder rather than the expected progression of renal vascular injury."],["A reversible lower-tract irritation without nephron loss","The established renal vascular damage can progress to irreversible filtration loss."]],"A patient with pressure-related renal vascular damage asks why preventing further injury remains important. Which long-term renal outcome is a concern?");
add("REN_nephrosclerosis__tests",[["Postvoid residual and peak urinary flow","These assess outflow rather than the principal pressure exposure and renal injury trend."],["Urine culture and temperature records","These evaluate infection rather than the longitudinal effects of hypertension on renal function."],["Daily voiding frequency and urgency scores","Storage symptoms do not directly track the renal filtration and protein consequences."]],"A patient with suspected hypertensive nephrosclerosis returns for follow-up. Which longitudinal measurements most directly track pressure exposure and renal effects?");
add("REN_nephrosclerosis__management",[["Treatment is needed chiefly when hypertension causes a headache","Renal and cardiovascular injury may progress without a dependable symptom warning."],["One normal reading means the damaged renal vessels have recovered","A single improved measurement does not establish reversal or eliminate the need for sustained control."],["Blood-pressure treatment addresses discomfort but not future renal risk","Consistent pressure management aims to limit further organ injury, not merely symptoms."]],"A patient with established pressure-related renal injury feels well and asks why consistent antihypertensive treatment is still needed. Which explanation best fits?");

add("REN_lupus_nephritis__risk",[["Absence of dysuria makes an upper-tract immune lesion unlikely","Lupus glomerular injury may develop without painful urination."],["Renal involvement is monitored only when a culture becomes positive","Immune renal disease does not require bacterial infection."],["Normal urine color reliably excludes abnormal protein excretion","Proteinuria can be present without visibly abnormal urine."]],"A patient with active SLE has no dysuria and asks why urine and renal function are repeatedly checked. Which explanation is most accurate?");
add("REN_lupus_nephritis__mechanism",[["Impaired proximal tubular reabsorption of small filtered proteins","Tubular proteinuria is a different mechanism; the biopsy establishes a glomerular filtration-barrier lesion."],["Overflow of excess circulating abnormal light-chain proteins","Overflow proteinuria is a different mechanism and is not supported by the documented lupus glomerular injury."],["Protein added by inflammation in the lower urinary tract","Postrenal protein contribution is different from the biopsy-confirmed glomerular leak."]],"A patient with SLE has biopsy-confirmed glomerular injury and increasing urinary protein. Which mechanism most directly explains the protein loss?");
add("REN_lupus_nephritis__signs",[["Cough-triggered leakage with complete emptying","That suggests a stress continence problem rather than glomerular injury."],["Urethral discharge after a sexual exposure","That points toward a different lower-tract inflammatory process."],["Urinary frequency alone without an abnormal urine sediment","Frequency alone is less specific for nephritic involvement."]],"A patient with SLE develops edema and increased blood pressure. Which additional urine finding most strengthens concern for renal inflammatory involvement?");
add("REN_lupus_nephritis__complications",[["A functional toileting disorder without renal tissue injury","Increasing proteinuria and declining eGFR indicate renal involvement rather than access-related accidents."],["A benign isolated storage symptom","This does not explain the worsening filtration and glomerular protein loss."],["A transient lower urinary irritation with preserved renal function","The sustained worsening renal markers indicate a risk beyond a short-lived lower-tract symptom."]],"Despite follow-up, a patient with lupus nephritis has increasing proteinuria and worsening eGFR. Which clinically important progression remains possible?");
add("REN_lupus_nephritis__tests",[["To directly measure the total volume of protein lost each day","Timed or ratio-based urine measurements quantify protein loss; tissue classification identifies the renal lesion and informs treatment."],["To directly quantify the whole-kidney filtration rate","Filtration is estimated or measured with functional methods rather than directly quantified by a tissue sample."],["To map a suspected collecting-system obstruction","Imaging defines outflow anatomy; the biopsy in this presentation classifies inflammatory renal tissue injury."]],"A patient with SLE has persistent substantial proteinuria and suspected renal inflammatory involvement. Why might tissue classification with a renal biopsy be recommended?");
add("REN_lupus_nephritis__management",[["Relieve bladder urgency as the principal target of the regimen","The prescribed plan targets active immune renal injury rather than a storage symptom."],["Eradicate presumed bacteria as the cause of the immune lesion","Immune-directed therapy addresses lupus inflammation, not presumed infection without evidence."],["Normalize symptoms before addressing the proteinuria and renal trend","Glomerular injury can progress despite limited symptoms, so treatment aims to preserve renal tissue and function."]],"A patient with active lupus nephritis begins an individualized immune-directed and kidney-protective regimen. Which goal best explains the combined plan?");

add("PATH_REN_AKI__AKI_prerenal",[["A ureteral obstruction produces sustained upstream pressure","Outflow is documented as unobstructed, while the case emphasizes circulatory loss."],["A primary nephrotoxin directly destroys tubular cells","No tubular toxin exposure or initial structural lesion is supplied."],["Immune glomerular inflammation lowers filtration","The immediate precipitant is major blood loss and hypoperfusion."]],"After acute hemorrhage, a patient becomes hypotensive and oliguric before evidence of structural renal injury appears. Urinary outflow is unobstructed. Which mechanism best describes the early AKI?");
add("PATH_REN_AKI__AKI_intrinsic",[["Prerenal hypoperfusion without structural renal injury","The case identifies direct tubular damage."],["Postrenal obstruction raising tubular pressure","Urinary drainage is documented as unobstructed."],["Stable chronic renal impairment without a superimposed acute change","The documented new creatinine rise and tubular injury establish an acute process."]],"A patient develops a creatinine rise after exposure to a nephrotoxic drug. Evaluation identifies renal tubular injury and patent urinary drainage. Which category fits this AKI?");
add("PATH_REN_AKI__AKI_postrenal",[["Insufficient renal blood delivery to initially intact tissue","That is a prerenal rather than the demonstrated obstructive mechanism."],["A primary immune-complex lesion of the glomerular filter","That is not the demonstrated obstructive mechanism."],["Direct nephrotoxic injury of renal tubular cells","That describes intrinsic injury rather than pressure from blocked drainage."]],"A patient has marked bladder distention, bilateral hydronephrosis, and worsening filtration from a documented outlet blockage. Which mechanism explains this postrenal injury?");
add("PATH_REN_CKD__CKD_bone",[["Isolated erythropoietin deficiency as the mechanism of the mineral pattern","Erythropoietin deficiency primarily affects red-cell production."],["Primary excess calcium absorption with normal phosphate excretion","That does not match retained phosphate and reduced active vitamin D."],["Autonomous parathyroid activity unrelated to the renal mineral changes","The linked phosphate and calcitriol findings support a secondary renal response."]],"Advanced CKD is accompanied by phosphate retention, reduced calcitriol, and rising PTH. Which linked process contributes to the patient's bone disorder?");
add("PATH_REN_CKD__CKD_anemia",[["Accelerated destruction of circulating red cells","The case reports no identified hemolysis and instead describes inadequate erythropoietin-associated marrow production."],["Continued red-cell loss through active bleeding","No bleeding is identified; the low production response supports the endocrine production defect."],["Insufficient iron available for hemoglobin synthesis","Iron deficiency is a possible contributor in CKD, but the case establishes adequate iron stores and an inadequate erythropoietin response."]],"A patient with CKD has low hemoglobin and reticulocyte production, adequate iron stores, no identified bleeding or hemolysis, and an inadequate erythropoietin response. Which production problem directly explains the endocrine contribution?");
add("PATH_REN_CKD__CKD_stages",[["G3a: mildly to moderately decreased GFR","G3a corresponds to a higher eGFR range than 24."],["G3b: moderately to severely decreased GFR","G3b corresponds to 30–44 rather than the supplied value."],["G5: kidney failure GFR category","G5 corresponds to eGFR below 15 rather than 24."]],"A patient's eGFR remains 24 mL/min/1.73 m² on repeated measurements over five months. Which GFR category applies to this persistent result?");
add("PATH_REN_AKI__AKI_phases",[["Worsening extracellular fluid retention caused by persistent anuria","The case describes increasing urine volume, not continued anuria."],["A new urethral obstruction causing the diuresis","Obstruction does not explain a recovery phase with markedly increased output and impaired concentration."],["Established restoration of normal concentrating and electrolyte handling","High urine volume can precede full recovery of tubular regulation."]],"During AKI recovery, a patient's urine output rises markedly while concentrating ability remains impaired. Which consequence should guide close fluid and electrolyte monitoring?");
add("REN_UTI__UTI_defenses",[["The ureterovesical junction normally limits reflux toward the kidneys","Anti-reflux anatomy is a different defense from the washout reduced by a large bladder residual."],["Urothelial barriers normally limit bacterial adhesion and invasion","Mucosal defenses are important, but the question specifically identifies loss of effective mechanical bladder emptying."],["Local antimicrobial factors normally inhibit microbial growth","Chemical defenses differ from the flushing effect specifically reduced by retained bladder urine."]],"A patient with a chronically large postvoid residual develops recurrent symptomatic urinary infections. Which normal mechanical defense is reduced by this retained urine?");

